HANDLE_QUOTED = re.compile(r"([\"']?" + HANDLE_NAME + r"[\"']?\s*[=:]\s*)([\"'])(.*?)\2", re.I)
HANDLE_PLAIN = re.compile(r"([\"']?" + HANDLE_NAME + r"[\"']?\s*[=:]\s*)[^\s,;\"'&}]+", re.I)
